# in half vertically or horizontally and merge overlapping cells

grid = [[int(x) for x in line.split()] for line in original_input.strip().split('\n')]
g = np.array(grid)
height, width = g.shape

# Try folding top half onto bottom half (keeping first occurrence)
fold_vertical_top = g.copy()
for r in range(height//2):
    r_mirror = height - 1 - r
    # Fold: where both are 7, keep 7; where one is 2, keep 2
